import sys

data = sys.stdin.read().split()
s = data[0]
cnt = {}
for ch in s:
    cnt[ch] = cnt.get(ch, 0) + 1
ans = -1
for i in range(len(s)):
    if cnt[s[i]] == 1:
        ans = i
        break
print(ans)

